insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_prioritise','prioritise','verb','to decide which tasks or needs are most important and deal with them first','[{"senseId":"prioritise_1","meaning":"to decide which tasks or needs are most important and deal with them first","acceptedParaphrases":["give first place to","decide what matters most and do it first"],"masteryContexts":[{"contextId":"u6_41_prioritise_meaning","text":"Students who prioritise the topics they find hardest usually make faster progress than those who revise only their favourite topics.","meaning":"to deal first with the most important tasks","wrongMeanings":["to write all the tasks in a tidy list","to avoid the tasks that seem difficult","to share the tasks equally with others"]},{"contextId":"u6_41_prioritise_paraphrase","text":"During the flood, the rescue team had to prioritise families with babies and elderly relatives, and bring everyone else out later.","meaning":"to decide who needs help first","wrongMeanings":["to choose who is allowed to leave","to ask who is able to pay","to check who has arrived early"]}],"situationDistractors":["The bakery on the corner opens its doors at six, and a queue forms outside.","Leila painted her bedroom wall pale yellow on Sunday afternoon.","A cyclist stopped at the red light and checked his phone.","The harbour ferry leaves at noon and crosses to the island.","Grandfather fed the chickens and then collected the warm eggs.","Snow fell all night, so the school bus did not run on Monday."],"gapDistractors":[{"contextId":"u6_41_prioritise_gap_1","answer":"prioritise","wrong":["travel","dress","paint"]},{"contextId":"u6_41_prioritise_gap_2","answer":"prioritise","wrong":["invite","photograph","insure"]},{"contextId":"u6_41_prioritise_gap_3","answer":"prioritise","wrong":["visit","paint","repair"]}],"spellingErrors":["priotise","prioritice","prioratise","prioritiese","priortise","prioritis"],"wordFamilyForms":[{"form":"prioritise","partOfSpeech":"verb","example":"Busy managers must prioritise urgent tasks over routine ones.","pedagogicallyUseful":true},{"form":"priority","partOfSpeech":"noun","example":"Safety is the first priority for the rescue team.","pedagogicallyUseful":true,"altExample":"Reducing waiting times has become a priority for many city hospitals."},{"form":"prioritisation","partOfSpeech":"noun","example":"Careful prioritisation helped the hospital to treat the most serious cases first.","pedagogicallyUseful":true,"altExample":"The report recommends better prioritisation of repairs to the oldest bridges."}],"masteryPassages":[{"passageId":"u6_41_prioritise_passage_1","contextId":"u6_41_prioritise_gap_1","text":"A new teacher has marking, planning and a parents’ meeting to finish before Friday. She cannot do everything at once, so she decides to ____ the work with the nearest deadline and leave the rest until later.","answer":"prioritise"},{"passageId":"u6_41_prioritise_passage_2","contextId":"u6_41_prioritise_gap_2","text":"The rescue team reached the flooded village with only two boats. They had to ____ the families with babies and elderly relatives, and bring the others out later.","answer":"prioritise"}],"contextDependentParaphrases":[],"wrongParaphrases":["make a list of","look back at","keep away from"],"misleadingDistractors":["to write all the tasks in a tidy list","to avoid the tasks that seem difficult","to share the work equally with other people"],"teacherNote":"Taught as a verb: to decide which tasks or needs are most important and deal with them first (prioritise tasks, prioritise patients). It is not the same as organise: making a list or a timetable does not in itself prioritise. British spelling: prioritise."}]'::jsonb,'["priority","prioritisation"]'::jsonb,'["prioritise tasks","prioritise your time","prioritise urgent work"]'::jsonb,'live'),
('vocab_retain','retain','verb','to keep information in your memory or continue to have something','[{"senseId":"retain_1","meaning":"to keep information in your memory or continue to have something","acceptedParaphrases":["remember and keep","keep in your memory"],"masteryContexts":[{"contextId":"u6_42_retain_meaning","text":"Older adults often retain vivid memories of their school days, even when they forget what happened last week.","meaning":"to keep information in the memory","wrongMeanings":["to write information in a book","to share information with a friend","to understand information fully"]},{"contextId":"u6_42_retain_paraphrase","text":"The company hopes to retain its best employees by offering training and clear opportunities for promotion.","meaning":"to continue to have something","wrongMeanings":["to look for new people to employ","to ask people to leave their jobs","to train people for different jobs"]}],"situationDistractors":["The visitors photographed the old stone bridge and bought postcards.","Marco mended the garden fence and painted it dark green.","The orchestra tuned their violins before the concert began.","A shepherd drove the flock across the road and closed the gate.","Hana packed her suitcase and called a taxi to the station.","The linesman raised his flag, and the match restarted with a free kick."],"gapDistractors":[{"contextId":"u6_42_retain_gap_1","answer":"retain","wrong":["forget","ignore","regret"]},{"contextId":"u6_42_retain_gap_2","answer":"retain","wrong":["invent","buy","repair"]},{"contextId":"u6_42_retain_gap_3","answer":"retain","wrong":["lose","sell","borrow"]}],"spellingErrors":["retane","reatain","retian","retaine","ritain","retayn"],"masteryPassages":[{"passageId":"u6_42_retain_passage_1","contextId":"u6_42_retain_gap_1","text":"Some students read a chapter three times and still forget it by the next morning. Others close the book, write down what they remember and find that they ____ far more.","answer":"retain"},{"passageId":"u6_42_retain_passage_2","contextId":"u6_42_retain_gap_2","text":"A good employer knows that training new staff is expensive. For that reason, many companies try hard to ____ their best workers by offering fair pay and chances to progress.","answer":"retain"}],"contextDependentParaphrases":[],"wrongParaphrases":["read and copy","listen and forget","write and share"],"misleadingDistractors":["to copy information onto paper","to hand information back to a teacher","to forget information after a short time"],"teacherNote":"Taught in its learning and memory sense: to keep information in your memory (retain information). The sense of continuing to have something (retain a good employee) is secondary. It is not the same as understand: a person can retain a fact without understanding it. The physical sense of holding an object is not taught here."}]'::jsonb,'[]'::jsonb,'["retain information","retain knowledge","retain what you learn"]'::jsonb,'live'),
('vocab_summarise','summarise','verb','to give the main points of something in a shorter form','[{"senseId":"summarise_1","meaning":"to give the main points of something in a shorter form","acceptedParaphrases":["give the main points of","say briefly what is in"],"masteryContexts":[{"contextId":"u6_43_summarise_meaning","text":"The news programme will summarise the day’s events in two minutes, so that listeners can catch up quickly.","meaning":"to give the main points in a shorter form","wrongMeanings":["to repeat every detail in full","to give a personal opinion about it","to copy the words exactly from it"]},{"contextId":"u6_43_summarise_paraphrase","text":"A good report begins with a short paragraph that will summarise the main findings for readers who are short of time.","meaning":"to give the main points briefly","wrongMeanings":["to explain each result in detail","to criticise the way results were found","to ask readers to check the results"]}],"situationDistractors":["The children built a sandcastle and decorated it with shells.","Omar watered the plants on his balcony every evening.","The bus was late, so the passengers waited in the rain.","A waiter carried three bowls of soup to the corner table.","The mechanic changed the flat tyre and wiped his hands.","Chen walked home beside the river after the football match."],"gapDistractors":[{"contextId":"u6_43_summarise_gap_1","answer":"summarise","wrong":["copy","praise","replace"]},{"contextId":"u6_43_summarise_gap_2","answer":"summarise","wrong":["attend","cancel","record"]},{"contextId":"u6_43_summarise_gap_3","answer":"summarise","wrong":["print","borrow","photograph"]}],"spellingErrors":["sumarise","summerise","summarice","summarrise","summariese","sumerise"],"masteryPassages":[{"passageId":"u6_43_summarise_passage_1","contextId":"u6_43_summarise_gap_1","text":"The examiner did not want the writer’s opinion or every small example. She asked students to ____ the passage in about fifty words, using only the main points.","answer":"summarise"},{"passageId":"u6_43_summarise_passage_2","contextId":"u6_43_summarise_gap_2","text":"Millions of people read the headline and the first paragraph and then stop. For this reason, news writers try to ____ the whole story in the opening sentences.","answer":"summarise"}],"contextDependentParaphrases":[],"wrongParaphrases":["give every detail of","give an opinion on","give a copy of"],"misleadingDistractors":["to copy the whole text word for word","to give your own opinion about the text","to explain every detail in a longer form"],"teacherNote":"To give the main points of something in a shorter form (summarise a text, summarise the main points). It is not copying, it does not repeat every detail, and it does not give your own opinion. British spelling: summarise."}]'::jsonb,'[]'::jsonb,'["summarise the main points","summarise a text","briefly summarise"]'::jsonb,'live'),
('vocab_coordination','coordination','noun','the organisation of people, actions or parts so that they work together effectively','[{"senseId":"coordination_1","meaning":"the organisation of people, actions or parts so that they work together effectively","acceptedParaphrases":["organised teamwork","planning so that people work together"],"masteryContexts":[{"contextId":"u6_44_coordination_meaning","text":"Building a stadium requires careful coordination among architects, engineers, builders and city officials.","meaning":"the organisation of people so that they work together","wrongMeanings":["the competition between people for the same job","the payment of people for their work","the choice of people for a team"]},{"contextId":"u6_44_coordination_paraphrase","text":"Reading aloud while listening for mistakes demands coordination between the eyes, ears and brain, which is why it is hard for beginners.","meaning":"the working together of different parts of the mind","wrongMeanings":["the choice between two parts of the brain","the damage caused to the eyes and ears","the long time that learning takes"]}],"situationDistractors":["The market sold fish, fruit and brightly coloured scarves.","Alicia sat by the window and watched the rain fall on the street.","The pilot landed the plane safely despite the strong wind.","Tom filled the kettle and made tea for his guests.","The museum closes at five o’clock on weekdays.","At dawn, the baker pulled warm rolls from the oven."],"gapDistractors":[{"contextId":"u6_44_coordination_gap_1","answer":"coordination","wrong":["competition","invitation","punishment"]},{"contextId":"u6_44_coordination_gap_2","answer":"coordination","wrong":["weight","colour","reputation"]},{"contextId":"u6_44_coordination_gap_3","answer":"coordination","wrong":["distance","weather","payment"]}],"spellingErrors":["cooordination","coordenation","cordination","coordinaton","coordinasion","coordnation"],"wordFamilyForms":[{"form":"coordination","partOfSpeech":"noun","example":"Good coordination between the police and the fire service saved many lives.","pedagogicallyUseful":true},{"form":"coordinate","partOfSpeech":"verb","example":"The project manager must coordinate the work of five different teams.","pedagogicallyUseful":true,"altExample":"Volunteers will coordinate the traffic outside the stadium before the match."},{"form":"coordinated","partOfSpeech":"adjective","example":"A coordinated response from several countries is needed to deal with the pollution.","pedagogicallyUseful":true,"altExample":"The rescue was carefully coordinated by three different agencies."}],"masteryPassages":[{"passageId":"u6_44_coordination_passage_1","contextId":"u6_44_coordination_gap_1","text":"Hundreds of buses, trains and ambulances had to be sent to the stadium on the same day. Without good ____ between the transport services, the crowds could not have been moved safely.","answer":"coordination"},{"passageId":"u6_44_coordination_passage_2","contextId":"u6_44_coordination_gap_2","text":"Playing the piano with both hands needs more than finger strength. It depends on the ____ of eyes, ears and hands, which the brain must learn to combine.","answer":"coordination"}],"contextDependentParaphrases":[],"wrongParaphrases":["friendly competition","private study","sudden change"],"misleadingDistractors":["a willingness to help other people","competition between rival groups","a rule that all workers must obey"],"teacherNote":"Uncountable noun: the organisation of people, actions or parts so that they work together effectively (coordination between teams). It is more than cooperation alone, which means only a willingness to help; coordination needs a plan. The body-movement sense is not the focus here."}]'::jsonb,'["coordinate","coordinated"]'::jsonb,'["coordination between teams","poor coordination","careful coordination"]'::jsonb,'live'),
('vocab_cognitive','cognitive','adjective','connected with thinking, understanding, learning or memory','[{"senseId":"cognitive_1","meaning":"connected with thinking, understanding, learning or memory","acceptedParaphrases":["thinking and learning","connected with the brain"],"masteryContexts":[{"contextId":"u6_45_cognitive_meaning","text":"Learning a second language is a cognitive challenge, because you must remember new words and also understand how sentences are built.","meaning":"connected with thinking and learning","wrongMeanings":["connected with the body and its movement","connected with money and payment","connected with the home and family"]},{"contextId":"u6_45_cognitive_paraphrase","text":"Doctors found that regular walking improved the cognitive performance of older patients, who solved problems more quickly.","meaning":"connected with thinking and memory","wrongMeanings":["connected with sport and exercise","connected with feelings and moods","connected with age and health"]}],"situationDistractors":["The runner stretched her legs and tied her laces.","Heavy traffic slowed the bus on the way to the airport.","My aunt planted tomatoes and beans in her garden.","The potter shaped the clay and placed the bowl in the kiln.","Rain fell steadily on the roof of the old barn.","The shop assistant wrapped the gift in blue paper."],"gapDistractors":[{"contextId":"u6_45_cognitive_gap_1","answer":"cognitive","wrong":["legal","financial","political"]},{"contextId":"u6_45_cognitive_gap_2","answer":"cognitive","wrong":["athletic","musical","financial"]},{"contextId":"u6_45_cognitive_gap_3","answer":"cognitive","wrong":["legal","financial","medical"]}],"spellingErrors":["cognative","cogntive","cognitiv","cognetive","conitive","cognitve"],"masteryPassages":[{"passageId":"u6_45_cognitive_passage_1","contextId":"u6_45_cognitive_gap_1","text":"Researchers tested children on memory, language and problem-solving. These ____ skills improved most in the group that had slept for more than nine hours.","answer":"cognitive"},{"passageId":"u6_45_cognitive_passage_2","contextId":"u6_45_cognitive_gap_2","text":"A tired driver may be fit and strong but still react slowly. The problem is not physical but ____: lack of sleep makes it harder to think clearly and decide quickly.","answer":"cognitive"}],"contextDependentParaphrases":[],"wrongParaphrases":["physical and social","musical and artistic","legal and financial"],"misleadingDistractors":["connected with the body and its movement","connected with subjects taught at school","connected with money and payment"],"teacherNote":"Adjective, usually before a noun (cognitive skills, cognitive development): connected with thinking, understanding, learning or memory. It is not the same as academic, which means connected with school study. Keep the idea simple: how the mind works."}]'::jsonb,'[]'::jsonb,'["cognitive skills","cognitive development","cognitive ability"]'::jsonb,'live'),
('vocab_achievement_6','achievement','noun','something successfully completed through effort or ability','[{"senseId":"achievement_6_1","meaning":"something successfully completed through effort or ability","acceptedParaphrases":["success earned by effort","result of hard work"],"masteryContexts":[{"contextId":"u6_46_achievement_6_meaning","text":"Climbing the mountain without extra oxygen was the greatest achievement of his sporting career.","meaning":"something successfully done through effort","wrongMeanings":["a prize given for taking part","an accident that was avoided","a plan that was never finished"]},{"contextId":"u6_46_achievement_6_paraphrase","text":"The school’s main achievement this year was to cut its energy use by a third.","meaning":"an important result reached through effort","wrongMeanings":["a rule introduced by the school","a problem that the school faced","a cost that the school paid"]}],"situationDistractors":["Two neighbours shared a taxi to the railway station.","The guide led the group along the narrow streets to the market.","Rosa cleaned the kitchen and put the dishes away.","A thunderstorm cancelled the open-air film on Friday evening.","The shopkeeper counted the coins and locked the till.","Dev lent his umbrella to a stranger at the bus stop."],"gapDistractors":[{"contextId":"u6_46_achievement_6_gap_1","answer":"achievement","wrong":["rumour","schedule","shortage"]},{"contextId":"u6_46_achievement_6_gap_2","answer":"achievement","wrong":["absence","opinion","habit"]},{"contextId":"u6_46_achievement_6_gap_3","answer":"achievement","wrong":["hunger","distance","weather"]}],"spellingErrors":["acheivement","achievment","achievemant","acheivment","achivement","achievemnet"],"wordFamilyForms":[{"form":"achievement","partOfSpeech":"noun","example":"Winning the science prize was a remarkable achievement for such a small school.","pedagogicallyUseful":true},{"form":"achieve","partOfSpeech":"verb","example":"It takes years of practice to achieve fluency in a second language.","pedagogicallyUseful":true,"altExample":"Few athletes achieve their best results in their first season."},{"form":"achievable","partOfSpeech":"adjective","example":"Set targets that are achievable, so that you do not lose motivation.","pedagogicallyUseful":true,"altExample":"A target of ten new words a day is achievable for most learners."}],"masteryPassages":[{"passageId":"u6_46_achievement_6_passage_1","contextId":"u6_46_achievement_6_gap_1","text":"When the team won the cup, nobody pretended that it had been easy. They had trained twice a day for a year, so the title was a genuine ____ rather than a lucky result.","answer":"achievement"},{"passageId":"u6_46_achievement_6_passage_2","contextId":"u6_46_achievement_6_gap_2","text":"The prize is not given for good luck or for taking part. It is awarded for an outstanding ____ that required years of study and careful work.","answer":"achievement"}],"contextDependentParaphrases":[],"wrongParaphrases":["luck without any effort","prize given to everyone","plan made for later"],"misleadingDistractors":["a result that happened by luck alone","a plan for what to do in the future","a prize given to every student"],"teacherNote":"Unit 6 item (achievement_6), separate from the Unit 1 achievement item; shares only the lexical spelling list. Sense: something successfully completed through effort or ability (a major achievement, a sense of achievement). It is not the same as outcome, which is any final result, good or bad; an achievement needs effort."}]'::jsonb,'["achieve","achievable"]'::jsonb,'["a major achievement","a sense of achievement","academic achievement"]'::jsonb,'live'),
('vocab_outcome','outcome','noun','the final result of a process, action or situation','[{"senseId":"outcome_1","meaning":"the final result of a process, action or situation","acceptedParaphrases":["final result","what happens in the end"],"masteryContexts":[{"contextId":"u6_47_outcome_meaning","text":"The outcome of the experiment surprised the researchers, because the plant grew faster in the dark.","meaning":"the final result of a test","wrongMeanings":["the plan for a test","the question asked in a test","the equipment used in a test"]},{"contextId":"u6_47_outcome_paraphrase","text":"Doctors compared how patients who received the new treatment recovered, and the outcome was clearly better.","meaning":"the final result of a treatment","wrongMeanings":["the price of a treatment","the reason for a treatment","the length of a treatment"]}],"situationDistractors":["The family sat on the grass and shared a picnic lunch.","A neighbour’s dog barked at the postman every morning.","The tailor measured the customer’s arm and wrote the size on a card.","Wind blew the washing off the line and into the pond.","The class sang a song while the teacher played the guitar.","Nadia boiled the eggs and cut the bread into thick slices."],"gapDistractors":[{"contextId":"u6_47_outcome_gap_1","answer":"outcome","wrong":["invitation","appointment","temperature"]},{"contextId":"u6_47_outcome_gap_2","answer":"outcome","wrong":["colour","sentence","salary"]},{"contextId":"u6_47_outcome_gap_3","answer":"outcome","wrong":["uniform","ticket","journey"]}],"spellingErrors":["outcom","outcum","outkome","autcome","outcomme","outcame"],"masteryPassages":[{"passageId":"u6_47_outcome_passage_1","contextId":"u6_47_outcome_gap_1","text":"Before the experiment began, the scientists wrote down what they expected to see. When the ____ turned out to be different, they repeated the test twice to be sure.","answer":"outcome"},{"passageId":"u6_47_outcome_passage_2","contextId":"u6_47_outcome_gap_2","text":"Every decision has consequences. A careful manager considers not only what she wants, but also what the likely ____ will be if the plan goes wrong.","answer":"outcome"}],"contextDependentParaphrases":[],"wrongParaphrases":["first idea","main aim","clear plan"],"misleadingDistractors":["a plan made before an event","an aim that someone hopes to reach","a guess about what will happen"],"teacherNote":"Noun: the final result of a process, action or situation (the outcome of the match, a positive outcome). It is not a goal, which is what you hope to reach, and it is not a prediction, which is what you think will happen. An outcome can be good or bad."}]'::jsonb,'[]'::jsonb,'["the outcome of","a positive outcome","the likely outcome"]'::jsonb,'live'),
('vocab_focus','focus','verb','to give full attention to something','[{"senseId":"focus_1","meaning":"to give full attention to something","acceptedParaphrases":["give full attention","keep your mind on one thing"],"masteryContexts":[{"contextId":"u6_48_focus_meaning","text":"When the match began, the goalkeeper tried to ignore the noise of the crowd and focus on the ball.","meaning":"to give full attention to something","wrongMeanings":["to look away from something","to move quickly towards something","to shout loudly at something"]},{"contextId":"u6_48_focus_paraphrase","text":"Surgeons train to focus completely during long operations, so that small interruptions do not affect their decisions.","meaning":"to keep full attention on a task","wrongMeanings":["to work faster on a task","to share a task with a colleague","to repeat a task many times"]}],"situationDistractors":["The tourists queued at the ticket office for nearly an hour.","Kemal bought a newspaper and left it on the train.","The farmer drove his tractor slowly along the narrow lane.","A parcel arrived on Tuesday with a note from her aunt.","The lifeguard blew her whistle and the swimmers left the pool.","Fresh paint covered the cracks in the old garage door."],"gapDistractors":[{"contextId":"u6_48_focus_gap_1","answer":"focus","wrong":["depend","vote","insist"]},{"contextId":"u6_48_focus_gap_2","answer":"focus","wrong":["rely","agree","insist"]},{"contextId":"u6_48_focus_gap_3","answer":"focus","wrong":["depend","agree","vote"]}],"spellingErrors":["focuss","fokus","focous","focas","fcous","foccus"],"masteryPassages":[{"passageId":"u6_48_focus_passage_1","contextId":"u6_48_focus_gap_1","text":"The pianist could hear people whispering in the audience and see a phone light in the third row. She closed her eyes and tried to ____ on the music alone.","answer":"focus"},{"passageId":"u6_48_focus_passage_2","contextId":"u6_48_focus_gap_2","text":"Switching between messages, videos and homework makes work slower. Many learners do better when they switch off notifications and ____ on one task for half an hour.","answer":"focus"}],"contextDependentParaphrases":[],"wrongParaphrases":["take a long break","make a quick guess","tell a short story"],"misleadingDistractors":["to look at something for a long time","to change from one task to another","to hurry through a task without thinking"],"teacherNote":"Taught as a verb: to give full attention to something (focus on a task). Focus is the action of directing attention; concentration is the ability or state of sustained attention, so focus is not the same as concentration. The camera and optical senses are not taught."}]'::jsonb,'[]'::jsonb,'["focus on","focus on a task","focus your attention"]'::jsonb,'live'),
('vocab_memorise','memorise','verb','to learn something so that you can remember it exactly','[{"senseId":"memorise_1","meaning":"to learn something so that you can remember it exactly","acceptedParaphrases":["learn exactly","learn by heart"],"masteryContexts":[{"contextId":"u6_49_memorise_meaning","text":"To pass the driving theory test, candidates must memorise the meaning of every road sign.","meaning":"to learn something so that you can remember it exactly","wrongMeanings":["to read something once without noting it","to understand why something is important","to write something down for later"]},{"contextId":"u6_49_memorise_paraphrase","text":"Emergency staff are trained to memorise the main steps of first aid so that they can act without looking at instructions.","meaning":"to learn steps so well that you do not need notes","wrongMeanings":["to practise steps only when others watch","to explain steps to other people","to choose which steps are important"]}],"situationDistractors":["The neighbours held a barbecue in the garden on Saturday.","A tourist asked for directions to the nearest post office.","The coach handed out new shirts before the tournament began.","Hot sun melted the ice cream before the children could eat it.","The shopkeeper rearranged the window display with winter coats.","The painter climbed the ladder and began to paint the ceiling."],"gapDistractors":[{"contextId":"u6_49_memorise_gap_1","answer":"memorise","wrong":["borrow","delete","measure"]},{"contextId":"u6_49_memorise_gap_2","answer":"memorise","wrong":["avoid","invent","protect"]},{"contextId":"u6_49_memorise_gap_3","answer":"memorise","wrong":["cancel","forbid","weigh"]}],"spellingErrors":["memorice","memoriese","memerise","memmorise","memorrise","momorise"],"wordFamilyForms":[{"form":"memorise","partOfSpeech":"verb","example":"Many children memorise the times tables before they understand why they work.","pedagogicallyUseful":true},{"form":"memory","partOfSpeech":"noun","example":"Regular sleep improves your memory and helps you to recall facts.","pedagogicallyUseful":true,"altExample":"The old man had a wonderful memory for names and faces."},{"form":"memorable","partOfSpeech":"adjective","example":"The final goal made it a memorable match for the whole town.","pedagogicallyUseful":true,"altExample":"A short rhyme can make a rule more memorable."}],"masteryPassages":[{"passageId":"u6_49_memorise_passage_1","contextId":"u6_49_memorise_gap_1","text":"The actor understood the story perfectly, but that was not enough. Before opening night he had to ____ every line, so that he could speak without looking at the script.","answer":"memorise"},{"passageId":"u6_49_memorise_passage_2","contextId":"u6_49_memorise_gap_2","text":"Pilots and nurses sometimes work in emergencies where there is no time to read instructions. That is why they ____ the key steps in advance until they can repeat them without a mistake.","answer":"memorise"}],"contextDependentParaphrases":[],"wrongParaphrases":["read quickly","guess easily","copy neatly"],"misleadingDistractors":["to understand how something works","to check an answer twice","to forget something after a short time"],"teacherNote":"To learn something so that you can remember it exactly (memorise key facts). It is not the same as understand: a student can memorise a rule without understanding it. British spelling: memorise."}]'::jsonb,'["memory","memorable"]'::jsonb,'["memorise key facts","memorise a list","memorise vocabulary"]'::jsonb,'live'),
('vocab_insight','insight','noun','a clear and often deeper understanding of a situation, problem or idea','[{"senseId":"insight_1","meaning":"a clear and often deeper understanding of a situation, problem or idea","acceptedParaphrases":["deeper understanding","clear understanding of a problem"],"masteryContexts":[{"contextId":"u6_50_insight_meaning","text":"The interviews gave the researchers a new insight into why young people leave small villages.","meaning":"a clear understanding of a situation","wrongMeanings":["a short report about a situation","a list of facts about a situation","a photo showing a situation"]},{"contextId":"u6_50_insight_paraphrase","text":"Her habit of asking one extra question showed real insight, because it exposed the weakness in the plan.","meaning":"a deeper understanding of a problem","wrongMeanings":["a quick answer to a problem","a plan to avoid a problem","a complaint about a problem"]}],"situationDistractors":["The farmers loaded the cart with apples and drove into town.","A thunderstorm rolled across the hills in the late afternoon.","Selim washed the car and then polished the windows.","The train to the coast leaves from platform six at noon.","Two sisters shared an umbrella on the walk to the shops.","Dinner was ready, and the family gathered around the table."],"gapDistractors":[{"contextId":"u6_50_insight_gap_1","answer":"insight","wrong":["argument","apology","excuse"]},{"contextId":"u6_50_insight_gap_2","answer":"insight","wrong":["holiday","complaint","tradition"]},{"contextId":"u6_50_insight_gap_3","answer":"insight","wrong":["furniture","permission","weather"]}],"spellingErrors":["insite","insihgt","insigt","insightt","insaight","inzight"],"masteryPassages":[{"passageId":"u6_50_insight_passage_1","contextId":"u6_50_insight_gap_1","text":"The statistics told the council how many people used the bus. The long conversations with passengers gave something more valuable: ____ into why some people refused to use it at all.","answer":"insight"},{"passageId":"u6_50_insight_passage_2","contextId":"u6_50_insight_gap_2","text":"Anyone can learn the facts of a historical event. A good historian goes further and offers ____ into its causes, showing why events happened as they did.","answer":"insight"}],"contextDependentParaphrases":[],"wrongParaphrases":["basic information","general opinion","popular belief"],"misleadingDistractors":["basic facts that everyone already knows","a quick guess made without thinking","a feeling of pride in your own ideas"],"teacherNote":"Noun: a clear and often deeper understanding of a situation, problem or idea (insight into, gain insight). It is more than basic information or simple awareness: an insight explains why or how something happens."}]'::jsonb,'[]'::jsonb,'["insight into","gain insight","valuable insight"]'::jsonb,'live')
